import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { getToken } from 'next-auth/jwt';

// Avalikud marsruudid — ei nõua sisselogimist
const publicRoutes = [
    '/auth/login',
    '/auth/register',
    '/auth/forgot-password',
    '/auth/reset-password',
    '/api/auth',
    '/api/health',
    '/api/documents',
    '/api/integrations/hubspot/callback',
    '/api/integrations/zoom/callback',
    '/api/integrations/salesforce/callback',
    '/api/integrations/slack/callback',
];

// Admin-only marsruudid
const adminRoutes = ['/admin/panel'];

export async function middleware(request: NextRequest) {
    const { pathname } = request.nextUrl;

    // Luba kõik avalikud marsruudid ja staatilised failid läbi
    const isPublic = publicRoutes.some((r) => pathname.startsWith(r));
    if (isPublic) return NextResponse.next();

    // Admin marsruutide kaitse
    if (adminRoutes.some((r) => pathname.startsWith(r))) {
        const token = await getToken({ req: request, secret: process.env.NEXTAUTH_SECRET });
        if (!token) {
            return NextResponse.redirect(new URL('/auth/login', request.url));
        }
        if ((token as any).role !== 'super_admin') {
            return NextResponse.redirect(new URL('/', request.url));
        }
        return NextResponse.next();
    }

    // Kõik muud marsruudid on avalikud (tasuta versioon — ei nõua auth'i)
    return NextResponse.next();
}

export const config = {
    matcher: [
        '/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)',
    ],
};